from __future__ import annotations

# ruff: noqa: E501
import json


def guided_home_html() -> str:
    return _shell(
        "EagleEye Guided User QA",
        r"""
<header class="top"><div><b>EagleEye</b> Guided User QA</div><a href="/">自動テスト・ダッシュボード</a></header>
<main>
  <section class="hero"><span class="eyebrow">AI-GUIDED / HUMAN-EXECUTED</span>
    <h1>シナリオを案内し、ユーザーがテストを消化する</h1>
    <p>これは自動テストとは別のユーザーテスト機能です。AIは手順を案内できますが、人の結果を上書きしません。Guided QA内のtelemetryを含め、この結果だけで自動リリースされることもありません。</p>
  </section>
  <div class="safe">CONSENT REQUIRED · USER / OBSERVER VERDICT · TELEMETRY OPTIONAL · AUDIT + SHA-256</div>
  <section><div class="section-head"><h2>シナリオ</h2><button class="ghost" onclick="loadAll()">更新</button></div><div id="scenarios" class="grid"></div></section>
  <section><div class="section-head"><h2>最近のユーザーテスト</h2></div><div id="sessions" class="list"></div></section>
</main>
<script>
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(path,opts={}){const r=await fetch(path,{headers:{'Content-Type':'application/json'},...opts});if(!r.ok){let d={};try{d=await r.json()}catch{}throw new Error(d.detail||r.statusText)}return r.json()}
async function startScenario(id){
  const observer=prompt('観察者がいる場合は名前を入力してください（任意）','')||'';
  const body={scenarioId:id,operatorAlias:'local-operator'};if(observer.trim())body.observerAlias=observer.trim();
  const receipt=await api('/api/v1/guided/sessions',{method:'POST',body:JSON.stringify(body)});location.href=receipt.runnerUrl;
}
function scenarioCard(s){const kinds=[...new Set(s.steps.map(x=>x.kind))].join(' / ');return `<article class="card"><div class="pill">${esc(s.steps.length)} STEPS · ${esc(kinds)}</div><h3>${esc(s.title)}</h3><p>${esc(s.description)}</p><div class="meta">対象: ${esc(s.targetSource)} · v${esc(s.version)}</div><button onclick="startScenario('${esc(s.id)}')">ユーザーテストを準備</button></article>`}
function sessionRow(s){const done=s.results.filter(r=>['PASSED','FAILED','BLOCKED'].includes(r.status)).length;return `<a class="row" href="/guided/${esc(s.id)}"><div><strong>${esc(s.scenarioId)}</strong><small>${esc(s.id)}</small></div><span>${done}/${s.results.length}</span><em class="status ${s.status.toLowerCase()}">${esc(s.status)}</em></a>`}
async function loadAll(){try{const [scenarios,sessions]=await Promise.all([api('/api/v1/guided/scenarios'),api('/api/v1/guided/sessions')]);document.querySelector('#scenarios').innerHTML=scenarios.map(scenarioCard).join('')||'<div class="empty">登録済みシナリオがありません。REST/MCPからシナリオJSONを登録できます。</div>';document.querySelector('#sessions').innerHTML=sessions.map(sessionRow).join('')||'<div class="empty">セッションはまだありません。</div>'}catch(e){document.querySelector('#scenarios').innerHTML=`<div class="error">${esc(e.message)}</div>`}}
loadAll();
</script>
""",
    )


def guided_runner_html(attestation_token: str) -> str:
    attestation_json = json.dumps(attestation_token).replace("<", r"\u003c").replace("&", r"\u0026")
    return _shell(
        "EagleEye Guided User QA Runner",
        rf"""
<header class="top"><div><b>EagleEye</b> Guided User QA</div><a href="/guided">シナリオ一覧</a></header>
<main class="runner">
  <div class="safe"><strong>USER TEST</strong> · 自動テストとは別 · AIは案内のみ · 人の合否を上書きしません</div>
  <section class="runner-head"><div><span id="course" class="eyebrow">LOADING</span><h1 id="title">セッションを読み込み中…</h1></div><div class="connection"><i id="conn-dot"></i><span id="connection">telemetry optional</span></div></section>
  <div class="progress"><div id="progress-bar"></div></div><div id="progress-label" class="progress-label"></div>
  <section id="stage" class="stage"><div class="empty">EagleEyeへ接続しています。</div></section>
  <section id="history" class="history"></section>
</main>
<script>
const SESSION_MATCH=/^\/guided\/(guided-[0-9a-f]{{32}})$/.exec(location.pathname);
if(!SESSION_MATCH)throw new Error('Invalid guided session URL');
const SESSION=SESSION_MATCH[1],ATTESTATION={attestation_json};let state=null,scenario=null,counting=false,lastStructure='';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}}[c]));
const safeColor=v=>/^#[0-9a-f]{{3}}([0-9a-f]{{3}}|[0-9a-f]{{5}})?$/i.test(String(v||''))?v:'#38d7c4';
async function api(path,opts={{}}){{const r=await fetch(path,{{headers:{{'Content-Type':'application/json'}},...opts}});if(!r.ok){{let d={{}};try{{d=await r.json()}}catch{{}}throw new Error(d.detail||r.statusText)}}return r.headers.get('content-type')?.includes('json')?r.json():r.text()}}
async function humanApi(path,opts={{}}){{return api(path,{{...opts,headers:{{'Content-Type':'application/json','X-EagleEye-Human-Attestation':ATTESTATION,...(opts.headers||{{}})}}}})}}
async function sendControl(action,extra={{}}){{try{{state=await humanApi(`/api/v1/guided/sessions/${{SESSION}}/control`,{{method:'POST',body:JSON.stringify({{action,expectedRevision:state.revision,...extra}})}});render()}}catch(e){{alert(e.message);await refresh()}}}}
async function approve(){{await sendControl('approve')}}
async function activate(){{if(counting)return;const missing=[...document.querySelectorAll('[data-condition]:not(:checked)')];if(missing.length){{alert('すべての試験条件を確認してください。');return}}counting=true;const confirmed=[...document.querySelectorAll('[data-condition]:checked')].map(x=>x.value);const step=currentStep();for(let n=step.countdownSeconds;n>0;n--){{document.querySelector('#countdown').textContent=n;await new Promise(r=>setTimeout(r,1000))}}document.querySelector('#countdown').textContent='開始';await sendControl('activate',{{confirmedConditions:confirmed}});counting=false}}
async function verdict(outcome){{const step=currentStep();let role='user';if(step.verdictAuthority==='observer')role='observer';else if(step.verdictAuthority==='either'&&state.observerAlias&&confirm('観察者として判定しますか？'))role='observer';const notes=prompt(outcome==='passed'?'気づき・使用感があれば入力してください（任意）':'状況を入力してください（再テストと修正案に使います）','')||'';const difficulty=Number(prompt('操作の難しさ 1（簡単）〜5（難しい）','3')||3);const confidence=Number(prompt('判定の確信度 1〜5','4')||4);try{{state=await humanApi(`/api/v1/guided/sessions/${{SESSION}}/feedback`,{{method:'POST',body:JSON.stringify({{outcome,reporterRole:role,difficultyRating:Math.min(5,Math.max(1,difficulty)),confidenceRating:Math.min(5,Math.max(1,confidence)),notes}})}});render()}}catch(e){{alert(e.message);await refresh()}}}}
function currentStep(){{return scenario.steps.find(x=>x.id===state.results[state.currentStepIndex].stepId)}}
function verdictClass(v){{return v==='PASSED'?'pass':v==='FAILED'?'fail':v==='BLOCKED'?'blocked':v==='MANUAL_REVIEW'?'warn':'active'}}
function requirements(step){{return step.requirementIds.map(id=>scenario.requirements.find(r=>r.id===id)).filter(Boolean)}}
function mediaUrl(media){{if(!media)return'';if(media.source==='local_asset')return '/api/v1/guided/assets/'+media.src.split('/').map(encodeURIComponent).join('/');return media.src}}
function markerHtml(m){{const c=safeColor(m.color),x=m.x*100,y=m.y*100,label=m.label?`<span>${{esc(m.label)}}</span>`:'';if(m.shape==='arrow'){{const dx=(m.toX-m.x)*100,dy=(m.toY-m.y)*100,len=Math.hypot(dx,dy),angle=Math.atan2(dy,dx)*180/Math.PI;return `<div class="marker arrow" style="left:${{x}}%;top:${{y}}%;width:${{len}}%;transform:rotate(${{angle}}deg);--mark:${{c}}">${{label}}</div>`}}if(m.shape==='point')return `<div class="marker point" style="left:${{x}}%;top:${{y}}%;--mark:${{c}}">${{label}}</div>`;return `<div class="marker ${{m.shape}}" style="left:${{x}}%;top:${{y}}%;width:${{m.width*100}}%;height:${{m.height*100}}%;--mark:${{c}}">${{label}}</div>`}}
function visual(step){{const g=step.guidance,m=g.media,remotePending=m&&m.source==='url'&&!state.approvedAtMs,img=remotePending?'<div class="blank-visual">承認後に外部参考画像を読み込みます</div>':m?`<img src="${{esc(mediaUrl(m))}}" alt="${{esc(m.alt)}}" referrerpolicy="no-referrer">`:'<div class="blank-visual">画面マーカー</div>',markers=g.markers.map(markerHtml).join('');if(!m&&!markers)return'';return `<div class="visual-surface">${{img}}${{markers}}</div>`}}
function timerLabel(result,step){{if(!result.startedAtMs)return'';const paused=result.status==='PAUSED',end=result.endedAtMs||Date.now(),active=Math.max(0,end-result.startedAtMs-result.accumulatedPauseMs-(paused&&result.pausedAtMs?end-result.pausedAtMs:0)),remaining=Math.max(0,step.timeoutMs-active);return `経過 ${{Math.floor(active/1000)}}秒 · 目安残り ${{Math.ceil(remaining/1000)}}秒`}}
function timer(result,step){{const label=timerLabel(result,step);return label?`<div class="timer" data-start="${{result.startedAtMs}}">${{label}}</div>`:''}}
function humanButtons(result){{if(result.manualVerdict)return `<div class="notice">${{esc(result.manualVerdict.reporterRole)}} の回答を記録済み。telemetry判定を待っています。</div>`;return `<div class="human-verdict"><p><b>実際に試した人が結果を入力してください。</b> PASSは自己申告/観察者報告として記録され、自動テストPASSとは区別されます。</p><button onclick="verdict('passed')">できた・期待どおり</button><button class="danger" onclick="verdict('failed')">できない・期待と違う</button><button class="ghost" onclick="verdict('blocked')">環境上実施できない</button></div>`}}
function controls(step,result){{
 if(state.status==='PREPARED')return `<div class="consent"><h3>開始前の承認</h3><p>${{esc(scenario.safetyNotice)}}</p><p>${{esc(scenario.privacyNotice)}}</p><p>AI/MCPはこの承認を代行できません。ユーザーが内容を確認して開始します。</p><button onclick="approve()">内容を確認し、ユーザーテストを承認</button></div>`;
 if(state.status==='READY'){{const conditions=step.requiredConditions.map(c=>`<label class="check"><input data-condition type="checkbox" value="${{esc(c)}}">${{esc(c)}}</label>`).join('');return `<div class="prep"><h3>準備</h3><p>${{esc(step.preparation)}}</p>${{conditions}}<button onclick="activate()">${{step.countdownSeconds}}秒後に開始</button><button class="ghost" onclick="sendControl('block',{{reason:'試験条件を準備できない'}})">今回は実施できない</button><div id="countdown" class="countdown"></div></div>`}}
 if(state.status==='PAUSED')return `<div class="capture"><h3>休憩中</h3>${{timer(result,step)}}<p>再開すると同じstepの残り時間から続行します。</p><button onclick="sendControl('resume')">テストを再開</button><button class="ghost" onclick="sendControl('block',{{reason:'休憩後も実施を継続できない'}})">実施不能として記録</button></div>`;
 if(result.status==='ACTIVE'){{const telemetry=step.telemetryOracle?`<div class="live">telemetry ${{result.observationCount}} · match ${{result.matchingObservations}} · drops ${{result.dropDelta}}</div>`:'';const human=step.kind!=='telemetry'||step.feedbackRequired?humanButtons(result):'<p>操作を続けてください。構造化telemetryを照合しています。</p>';return `<div class="capture"><h3>実施中 · ${{esc(step.kind)}}</h3>${{timer(result,step)}}${{telemetry}}${{human}}<button class="ghost" onclick="sendControl('pause')">休憩</button></div>`}}
 if(result.status==='AWAITING_FEEDBACK')return `<div class="feedback"><h3>telemetry条件は成立しました</h3>${{humanButtons(result)}}</div>`;
 if(['COMPLETED','FAILED','BLOCKED','ABORTED'].includes(state.status)){{const g=state.gate||{{}},hasFailure=['FAILED','BLOCKED'].includes(result.status),detail=hasFailure?`<div class="failure-detail"><h3>判定ログと修正案</h3>${{(result.failureCodes||[]).length?`<p><b>コード:</b> ${{result.failureCodes.map(esc).join(' / ')}}</p>`:''}}${{(result.verdictReasons||[]).map(x=>`<p class="reason">${{esc(x)}}</p>`).join('')}}${{(result.correctionSuggestions||[]).map(x=>`<p class="fix">修正案: ${{esc(x)}}</p>`).join('')}}</div>`:'',retest=state.retestSessionId?`<p class="notice">再テスト準備済み: <code>${{esc(state.retestSessionId)}}</code></p><a class="button" href="/guided/${{esc(state.retestSessionId)}}">失敗/BLOCKEDだけ再テスト</a>`:'';return `<div class="complete ${{verdictClass(g.decision)}}"><div class="verdict">${{esc(g.decision||state.status)}}</div><h3>ユーザーテスト終了</h3><p>成功率 ${{esc(g.passRatePercent??0)}}% · 自動リリース ${{g.releaseRecommended?'YES':'NO'}}</p><p class="notice">Guided QA単体ではtelemetry合格を含め常に自動リリース不可です。自動テストの代替ではありません。</p>${{(g.blockers||[]).map(x=>`<p class="reason">${{esc(x)}}</p>`).join('')}}${{(g.warnings||[]).map(x=>`<p class="notice">${{esc(x)}}</p>`).join('')}}${{detail}}${{retest}} <a class="button ghost" href="/api/v1/guided/sessions/${{SESSION}}/report">ログ・証跡レポート</a></div>`}}
 if(['PASSED','FAILED','BLOCKED'].includes(result.status)){{const retry=['FAILED','BLOCKED'].includes(result.status)?'<button class="ghost" onclick="sendControl(\'retry\')">このstepを再試行</button>':'';return `<div class="result ${{verdictClass(result.status)}}"><div class="verdict">${{esc(result.status)}}</div><p>証拠区分: <b>${{esc(result.evidenceClass)}}</b></p>${{result.verdictReasons.map(x=>`<p class="reason">${{esc(x)}}</p>`).join('')}}${{result.correctionSuggestions.map(x=>`<p class="fix">修正案: ${{esc(x)}}</p>`).join('')}}<button onclick="sendControl('next')">次のテストへ</button>${{retry}}</div>`}}
 return '<div class="empty">状態を更新しています。</div>'
}}
function structureKey(){{if(!state)return'';const result=state.results[state.currentStepIndex];return [state.status,state.currentStepIndex,result.status,result.attempt,Boolean(result.manualVerdict),result.telemetrySatisfied,state.retestSessionId||'',state.gate?.decision||''].join('|')}}
function updateDynamic(){{if(!state||!scenario)return;const result=state.results[state.currentStepIndex],step=currentStep(),connected=state.lastObservationAtMs&&Date.now()-state.lastObservationAtMs<5000;document.querySelector('#course').textContent=`${{scenario.id}} · ATTEMPT ${{state.attempt}} · REV ${{state.revision}}`;document.querySelector('#conn-dot').className=connected?'on':'';document.querySelector('#connection').textContent=connected?'telemetry 接続中':step.telemetryOracle?'telemetry 待機中':'手動テスト';const timerNode=document.querySelector('.timer');if(timerNode)timerNode.textContent=timerLabel(result,step);const live=document.querySelector('.live');if(live)live.textContent=`telemetry ${{result.observationCount}} · match ${{result.matchingObservations}} · drops ${{result.dropDelta}}`}}
function render(){{if(!state||!scenario)return;const result=state.results[state.currentStepIndex],step=currentStep(),done=state.results.filter(r=>['PASSED','FAILED','BLOCKED'].includes(r.status)).length,pct=Math.round(done/state.results.length*100);document.querySelector('#title').textContent=scenario.title;document.querySelector('#progress-bar').style.width=pct+'%';document.querySelector('#progress-label').textContent=`${{done}} / ${{state.results.length}} 消化 · STEP ${{state.currentStepIndex+1}}`;const req=requirements(step).map(r=>`<li><code>${{esc(r.id)}}</code> ${{esc(r.text)}}</li>`).join('');document.querySelector('#stage').innerHTML=`<div class="step-no">STEP ${{state.currentStepIndex+1}} / ${{state.results.length}} · ${{esc(step.kind.toUpperCase())}}</div><h2>${{esc(step.title)}}</h2><div class="instruction">${{esc(step.guidance.text)}}</div>${{step.guidance.hint?`<p class="hint">${{esc(step.guidance.hint)}}</p>`:''}}${{visual(step)}}<div class="expected"><b>期待結果</b><p>${{esc(step.expected)}}</p>${{req?`<ul>${{req}}</ul>`:''}}</div>${{controls(step,result)}}`;document.querySelector('#history').innerHTML='<h3>消化履歴</h3>'+state.results.map((r,i)=>`<div class="hist ${{i===state.currentStepIndex?'current':''}}"><span>${{i+1}}</span><b>${{esc(r.stepId)}} <small>${{esc(r.evidenceClass)}}</small></b><em class="${{verdictClass(r.status)}}">${{esc(r.status)}}</em></div>`).join('');lastStructure=structureKey();updateDynamic()}}
async function refresh(){{try{{state=await api(`/api/v1/guided/sessions/${{SESSION}}`);if(!scenario)scenario=await api(`/api/v1/guided/scenarios/${{state.scenarioId}}`);if(structureKey()!==lastStructure)render();else updateDynamic()}}catch(e){{document.querySelector('#stage').innerHTML=`<div class="error">${{esc(e.message)}}</div>`}}}}
refresh();setInterval(refresh,900);
</script>
""",
    )


def _shell(title: str, body: str) -> str:
    return f"""<!doctype html><html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="icon" href="data:,"><title>{title}</title>
<style>
:root{{--bg:#090d12;--surface:#111821;--surface2:#17212c;--line:#293847;--ink:#edf7f5;--muted:#93a7ad;--cyan:#38d7c4;--green:#61e7a4;--amber:#ffc861;--red:#ff7777;--blue:#75aaff}}*{{box-sizing:border-box}}body{{margin:0;background:radial-gradient(circle at 80% -20%,#153137 0,transparent 35%),var(--bg);color:var(--ink);font:15px/1.55 system-ui,"Segoe UI",sans-serif}}button,.button{{display:inline-block;border:0;border-radius:8px;padding:11px 16px;margin:4px 4px 4px 0;background:#168f82;color:white;font-weight:750;text-decoration:none;cursor:pointer}}button:hover,.button:hover{{background:#20b4a4}}button.ghost,.button.ghost,.ghost{{border:1px solid var(--line);background:transparent;color:var(--muted)}}button.danger{{background:#9d3e48}}a{{color:var(--cyan)}}.top{{height:58px;display:flex;align-items:center;justify-content:space-between;padding:0 24px;border-bottom:1px solid var(--line);background:#0a1017e8;position:sticky;top:0;z-index:5}}.top b{{color:var(--cyan)}}main{{max-width:1180px;margin:auto;padding:28px}}.hero{{max-width:800px;padding:34px 0 24px}}h1{{font-size:clamp(28px,4vw,46px);line-height:1.12;margin:8px 0 14px}}h2{{margin:7px 0 12px;font-size:27px}}h3{{margin:8px 0}}p{{color:var(--muted)}}.eyebrow{{font:700 11px/1.4 ui-monospace,monospace;letter-spacing:.16em;color:var(--cyan)}}.safe{{padding:12px 16px;border:1px solid #2b665d;border-radius:8px;background:#10241f;color:var(--green);font:700 12px/1.4 ui-monospace,monospace}}section{{margin:26px 0}}.section-head{{display:flex;align-items:center;justify-content:space-between}}.grid{{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:14px}}.card,.stage,.history{{border:1px solid var(--line);border-radius:10px;background:linear-gradient(145deg,var(--surface),#0e151d);padding:20px}}.card h3{{font-size:20px}}.card p{{min-height:72px}}.pill{{display:inline-block;padding:3px 8px;border:1px solid #2d5a55;border-radius:999px;color:var(--cyan);font:700 10px ui-monospace,monospace}}.meta{{margin:10px 0;color:var(--muted);font-size:12px}}.list{{display:grid;gap:8px}}.row{{display:grid;grid-template-columns:1fr auto auto;align-items:center;gap:18px;padding:12px 14px;border:1px solid var(--line);border-radius:8px;background:var(--surface);color:var(--ink);text-decoration:none}}.row small,.hist small{{display:block;color:var(--muted)}}.row em,.status{{font-style:normal;font-size:11px;color:var(--muted)}}.runner{{max-width:960px}}.runner-head{{display:flex;justify-content:space-between;align-items:flex-start}}.connection{{display:flex;align-items:center;gap:8px;color:var(--muted)}}.connection i{{width:9px;height:9px;border-radius:50%;background:var(--amber)}}.connection i.on{{background:var(--green);box-shadow:0 0 0 5px #61e7a418}}.progress{{height:7px;background:#1a2630;border-radius:9px;overflow:hidden}}#progress-bar{{height:100%;background:linear-gradient(90deg,#168f82,var(--cyan));transition:width .25s}}.progress-label{{margin:7px 0 18px;color:var(--muted);font-size:12px;text-align:right}}.stage{{min-height:510px;padding:30px}}.step-no{{font:700 11px ui-monospace,monospace;color:var(--cyan)}}.instruction{{margin:18px 0;padding:22px;border-left:4px solid var(--cyan);background:#0b1219;font-size:21px;font-weight:700;white-space:pre-wrap}}.hint{{padding:10px 14px;background:#161e28;color:#bed2da}}.visual-surface{{position:relative;width:100%;aspect-ratio:16/9;margin:16px 0;overflow:hidden;border:1px solid #34505f;border-radius:9px;background:#071017}}.visual-surface img{{width:100%;height:100%;object-fit:contain}}.blank-visual{{display:grid;height:100%;place-items:center;color:#49616c}}.marker{{position:absolute;border:3px solid var(--mark);color:var(--mark);filter:drop-shadow(0 0 3px #000);pointer-events:none}}.marker span{{position:absolute;left:0;top:100%;padding:2px 6px;background:#071017dd;color:var(--mark);white-space:nowrap;font-size:12px}}.marker.circle{{border-radius:50%}}.marker.point{{width:16px;height:16px;border-radius:50%;transform:translate(-50%,-50%);background:var(--mark)}}.marker.arrow{{height:3px;border:0;background:var(--mark);transform-origin:0 50%}}.marker.arrow:after{{content:'';position:absolute;right:-2px;top:-5px;border-left:11px solid var(--mark);border-top:6px solid transparent;border-bottom:6px solid transparent}}.expected{{padding:14px 17px;border:1px solid var(--line);border-radius:8px;background:var(--surface2)}}.expected p{{margin:4px 0}}.expected code{{color:var(--blue)}}.prep,.consent,.capture,.feedback,.result,.complete{{margin-top:18px;padding:20px;border:1px solid var(--line);border-radius:8px;background:#0c131a}}.check{{display:block;margin:9px 0;color:var(--ink)}}textarea{{width:100%;min-height:80px;margin:10px 0;padding:10px;border:1px solid var(--line);border-radius:7px;background:#080d12;color:var(--ink)}}.countdown{{min-height:64px;margin-top:14px;color:var(--cyan);font-size:46px;font-weight:900;text-align:center}}.live,.timer{{margin:12px 0;padding:10px;color:var(--cyan);background:#0a171b;font:700 13px ui-monospace,monospace}}.verdict{{font:900 31px ui-monospace,monospace}}.pass .verdict,.pass{{color:var(--green)}}.warn .verdict,.warn{{color:var(--amber)}}.fail .verdict,.fail{{color:var(--red)}}.blocked .verdict,.blocked{{color:var(--amber)}}.reason{{padding:9px 12px;background:#221519;color:#ffb1b1}}.fix{{padding:9px 12px;background:#18251e;color:#b5efd0}}.notice{{padding:9px 12px;background:#292313;color:#ffe09b}}.history{{margin-top:18px}}.hist{{display:grid;grid-template-columns:28px 1fr auto;gap:10px;padding:8px;border-top:1px solid var(--line)}}.hist.current{{background:#18312e}}.hist em{{font-style:normal;font-size:11px}}.empty,.error{{padding:30px;text-align:center;color:var(--muted)}}.error{{color:var(--red)}}@media(max-width:650px){{main{{padding:16px}}.runner-head{{display:block}}.stage{{padding:18px}}.instruction{{font-size:18px}}.row{{grid-template-columns:1fr auto}}.row em{{grid-column:1/-1}}}}
</style></head><body>{body}</body></html>"""
